from decimal import Decimal, InvalidOperation
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value: Any) -> Any:
    if isinstance(value, str):
        stripped = value.strip()
        return Decimal("0") if stripped == "" else Decimal(stripped)
    return value


def set_discount(
    order: dict,
    pct,
    user_id: str,
    users: list[dict],
) -> dict:
    try:
        numeric_pct = _numeric_value(pct)
        in_range = numeric_pct >= 0 and numeric_pct <= 100
    except (InvalidOperation, TypeError, ValueError):
        in_range = False

    if not in_range:
        raise BusinessRuleViolation("E5001", "Discount out of range")

    if numeric_pct > 20:
        role_id = ""
        for user in users:
            if user.get("DEL_FLG", "") == "Y":
                continue
            if user.get("USR_ID") == user_id:
                role_id = user.get("ROLE_ID", "")
                break

        if role_id not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    updated_order = order.copy()
    updated_order["DISC_PCT"] = pct
    return updated_order
